local _, addon = ...

addon.localeData.enUS.texts = {
 MARK={name="Mark of the Wild",ziel={"May the wilds watch over you, %s.","Root, wind and star strengthen you, %s.","*raises a hand toward %s as a gentle current stirs around them.*"},gruppe={"May the wilds watch over us.","Nature lend us strength and resilience.","*draws a slow circle in the air as leaves and wind answer the gesture.*"}},
 GIFT={name="Gift of the Wild",gruppe={"The blessing of the wilds be upon you all.","Many branches, one living whole.","*spreads both hands as the blessing settles over the group.*"}},
 THORNS={name="Thorns",ziel={"May the thorns guard you, %s.","Let every blow against you carry a price, %s.","*traces a protective gesture around %s as spectral thorns take shape.*"},gruppe={"The wilds are not defenseless.","Who reaches for us reaches into thorns.","*calls a ring of thorny growth around the companions.*"}},
 REJUVENATION={name="Rejuvenation",ziel={"New strength grow within you, %s.","Let nature ease your wounds, %s.","*rests a glowing hand near %s's wounds as fresh life begins to stir.*"},gruppe={"With every breath, strength returns.","Life returns one step at a time."}},
 REGROWTH={name="Regrowth",ziel={"Like new shoots after a storm, rise stronger, %s.","Nature close your wounds, %s.","*guides a surge of green life toward %s.*"},gruppe={"Even after the storm, the forest grows again.","Where there is life, healing can grow."}},
 HEALING_TOUCH={name="Healing Touch",ziel={"May the strength of the earth heal you, %s.","Stay with us, %s. Nature lends you strength.","*places a steady hand on %s and channels the calm strength of the wilds.*"},gruppe={"Nature grants us healing.","Life finds a way."}},
 TRANQUILITY={name="Tranquility",gruppe={"Be still and hear the forest breathe.","Let the noise of battle fade for a moment.","*lifts both hands as a calm green radiance settles over the companions.*"}},
 INNERVATE={name="Innervate",ziel={"Drink deeply from the current of life, %s.","May the wilds refill your spirit, %s.","*draws renewed natural power toward %s with a measured gesture.*"},gruppe={"The stream of life has not run dry.","From quiet springs comes new strength."}},
 REBIRTH={name="Rebirth",ziel={"Return to us, %s. Your path is not finished.","Life calls you by name, %s.","*kneels beside %s and calls upon the cycle of life to turn once more.*"},gruppe={"The cycle grants another chance.","Life calls a companion back."}},
 ROOTS={name="Entangling Roots",ziel={"Roots of the earth, hold %s fast!","No further, %s. The ground itself holds you.","*drives a hand toward the earth as roots lash up around %s.*"},gruppe={"Roots of the earth, hold fast!","Where roots take hold, the charge ends."}},
 MOONFIRE={name="Moonfire",ziel={"Moonlight finds you, %s.","Silver fire burn upon you, %s.","*points toward %s as a shard of cold moonlight descends.*"},gruppe={"Silver fire breaks the darkness.","The moon answers my call."}},
 WRATH={name="Wrath",gruppe={"Nature raises its voice.","Wind and earth answer my call.","*draws the force of the wilds into a sudden, violent surge.*"}},
 BARKSKIN={name="Barkskin",gruppe={"Like old bark, I endure the storm.","Today I do not break.","*sets their stance as rough bark spreads across the skin.*"}},
 BEAR={name="Bear Form",gruppe={"With the bear's strength I guard my companions.","Claws ready. I hold the line.","*drops into a powerful bear form with a deep growl.*"}},
 CAT={name="Cat Form",gruppe={"Quiet steps and sharp senses guide me.","Claws need no long speeches.","*flows into feline form and lowers into a silent hunting stance.*"}},
 TRAVEL={name="Travel Form",gruppe={"The wind shows me the way.","Where one path ends, another begins.","*shifts into a swift traveling form and surges forward.*"}},
 AQUATIC={name="Aquatic Form",gruppe={"The current carries me.","Beneath the surface waits another wilderness.","*changes into an aquatic form and slips into the water.*"}},
 MOONKIN={name="Moonkin Form",gruppe={"Under moon and stars I keep the balance.","The stars are distant. Their power is not.","*takes on moonkin form beneath a shimmer of astral light.*"}},
 TREE={name="Tree of Life",gruppe={"My roots hold; my branches bring healing.","Come closer. There is room beneath these branches.","*roots into the ground as the form of the Tree of Life takes shape.*"}},
 FLIGHT={name="Flight Form",gruppe={"The sky opens its paths to me.","The ground can wait. The sky is calling.","*spreads newly formed wings and rises into the open air.*"}},
}
